#ifndef CORE_TYPES_H
#define CORE_TYPES_H

#include <stdint.h>
#include <stdbool.h>

// KI-Agent unterstützt: Refactoring core types

// Team definitions
#define DEAD 0
#define TEAM_RED 1
#define TEAM_BLUE 2
#define MAX_ROUNDS 1000

typedef enum {
    TEAM_NONE = DEAD,
    TEAM_1 = TEAM_RED,
    TEAM_2 = TEAM_BLUE
} Team;

typedef enum {
    STATE_PUZZLE,   // Tutorial/Onboarding
    STATE_CONFIG,
    STATE_EDIT_RED,
    STATE_EDIT_BLUE,
    STATE_IGNITION, // Dramatic reveal countdown
    STATE_LOAD,     // For browsing protocol archive
    STATE_RUNNING,
    STATE_OBSERVER,
    STATE_FINISHED, 
    STATE_GAME_OVER
} AppState;

typedef struct {
    int level;
    int target_pop;
    char hint[256];
} PuzzleConfig;

typedef struct {
    int rows;
    int cols;
    int delay_ms;
    int max_population;
    int max_rounds;
    // Current counters needed for UI display
    int current_red_pop;
    int current_blue_pop;
    int current_round;
    // Catalyst Tracking
    bool red_catalyst_used;
    bool blue_catalyst_used;
    // Telemetry Arrays (Dynamically allocated based on max_rounds)
    int *history_red_pop;
    int *history_blue_pop;
    int history_count;
} GameConfig;

typedef struct {
    int *grid; // Pointer to flat array: row-major order
    int rows;
    int cols;

    // Spatial Partitioning (NEW for Epic Scale)
    unsigned char *chunk_map; // 1D array: 1 = active, 0 = dead
    int chunk_rows;
    int chunk_cols;
} World;

// KI-Agent unterstützt: Results of a single match
typedef struct {
    int winner; // 1 = Red, 2 = Blue, 0 = Draw
    int red_final_pop;
    int blue_final_pop;
    int stable_at_generation; // 0 if never reached stable state
} MatchResult;

#endif // CORE_TYPES_H

