        return {"status": "SUCCESS", "duration": duration, "cpu_time": out_data['execution_time_cpu_s']}
    except subprocess.TimeoutExpired:
        print("TIMEOUT (>120s)")
        return {"status": "TIMEOUT", "duration": 120}

